-- Existing container-local identity; session forced read-only; no content, input/output or credentials exported.
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT jsonb_build_object('kind','identity','at',now(),'read_only',current_setting('transaction_read_only'),'database',current_database());
SELECT jsonb_build_object('kind','runtime_runs','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT agent_id,task_type,success,count(*) n,min(created_at) first_at,max(created_at) last_at FROM djimit_agent_runtime.agent_runs GROUP BY 1,2,3) x;
SELECT jsonb_build_object('kind','runtime_skill_use','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT skill_id,agent_id,task_type,success,count(*) n,avg(latency_ms) mean_ms,count(token_usage) token_objects,count(corrections) correction_objects,min(created_at) first_at,max(created_at) last_at FROM djimit_agent_runtime.skill_usage_events GROUP BY 1,2,3,4) x;
SELECT jsonb_build_object('kind','runtime_memory_use','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT agent_id,action,count(*) n,avg(usefulness_score) mean_reported_usefulness,max(created_at) last_at FROM djimit_agent_runtime.memory_usage_events GROUP BY 1,2) x;
SELECT jsonb_build_object('kind','runtime_skill_evaluators','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT evaluator,count(*) n,min(created_at) first_at,max(created_at) last_at FROM djimit_agent_runtime.skill_evaluations GROUP BY 1) x;
SELECT jsonb_build_object('kind','runtime_eval_keys','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT k,count(*) n FROM djimit_agent_runtime.skill_evaluations e CROSS JOIN LATERAL jsonb_object_keys(e.result) k GROUP BY k) x;
SELECT jsonb_build_object('kind','central_skills','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT skill_id,skill_type,status,quality_score,usage_count,successful_usage_count,manifest->>'version' version,updated_at FROM djimit_central_memory.skills ORDER BY skill_id) x;
SELECT jsonb_build_object('kind','central_skill_usage','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT agent_id,task_type,success,count(*) n,count(DISTINCT skill_id) skills,max(created_at) last_at FROM djimit_central_memory.skill_usage GROUP BY 1,2,3) x;
SELECT jsonb_build_object('kind','central_memory','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT memory_type,status,count(*) n,sum(retrieval_count) retrievals,sum(usage_count) uses,sum(successful_usage_count) successful_uses,sum(ignored_count) ignored,sum(contradiction_count) contradictions,max(last_used_at) last_use FROM djimit_central_memory.memories GROUP BY 1,2) x;
SELECT jsonb_build_object('kind','central_eval_keys','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT k,count(*) n FROM djimit_central_memory.skill_evaluations e CROSS JOIN LATERAL jsonb_object_keys(e.result) k GROUP BY k) x;
SELECT jsonb_build_object('kind','central_projection','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT projection_target,status,count(*) n,min(created_at) oldest,max(processed_at) last_processed FROM djimit_central_memory.projection_outbox GROUP BY 1,2) x;
SELECT jsonb_build_object('kind','central_episode_types','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT episode_type,count(*) n,max(created_at) last_at FROM djimit_central_memory.episodes GROUP BY 1) x;
SELECT jsonb_build_object('kind','runtime_swarm','rows',jsonb_agg(to_jsonb(x))) FROM (SELECT run_id,task_complexity,selected_agents,selected_skills,memory_ids,success,created_at FROM djimit_agent_runtime.swarm_runs) x;
ROLLBACK;
